HEADER = """<a class="skip-link" href="#main-content">Skip to main content</a><header><a href="/">Brand System Maker</a><nav aria-label="Primary"><a href="/brand-systems">Living brands</a><a href="/brands">Kit library</a></nav></header>"""
DERIVATIVE_TOOLS = """<section class="derivative-tools" aria-labelledby="derivative-heading"><h3 id="derivative-heading">Create logo variants and icons</h3><p class="field-help">Choose an uploaded or generated raster logo. The source stays unchanged; every result is added as an optional managed asset.</p><label for="derivative-source">Source raster logo</label><select id="derivative-source"><option value="">Choose a raster logo</option></select><fieldset><legend>AI variants</legend><label><input type="checkbox" name="logo-variant" value="monochrome" checked> Monochrome</label><label><input type="checkbox" name="logo-variant" value="inverted" checked> Inverted</label><label><input type="checkbox" name="logo-variant" value="horizontal-lockup" checked> Horizontal lockup</label><label><input type="checkbox" name="logo-variant" value="icon-only" checked> Icon only</label></fieldset><div class="button-row"><button id="create-favicon-set" type="button">Create favicon + app icons</button><button id="create-logo-variants" type="button">Create selected AI variants</button><button id="create-vector" type="button">Vectorize to SVG</button></div><p id="derivative-status" role="status" aria-live="polite"></p></section>"""

BRIEF_PANEL = """<section class="brief-panel" aria-labelledby="brief-heading"><h2 id="brief-heading">Founding brief</h2><p class="field-help">Fill only what you know. Every field saves after you pause, and unresolved questions are useful evidence—not a failure.</p><p id="brief-entry-path" class="eyebrow"></p><form id="brief-form"><div class="suggestion-row" aria-label="Suggested brief answers"><button type="button" data-brief-suggestion="objective" data-value="Turn this idea into a clear, usable brand system.">Use a starter objective</button><button type="button" data-brief-suggestion="audience" data-value="People deciding whether this project is right for them.">Use a starter audience</button><button type="button" data-brief-suggestion="success-measures" data-value="A new visitor can explain the project accurately after one minute.">Use a starter success measure</button></div><label for="brief-objective">Objective</label><textarea id="brief-objective" rows="3" maxlength="50000"></textarea><label for="brief-audience">Audience</label><textarea id="brief-audience" rows="3" maxlength="50000"></textarea><label for="brief-category">Category or frame of reference</label><textarea id="brief-category" rows="3" maxlength="50000"></textarea><label for="brief-existing-equity">What must be preserved?</label><textarea id="brief-existing-equity" rows="3" maxlength="50000"></textarea><details><summary>More brief fields</summary><p class="field-help">Use one item per line. Leave anything unknown blank.</p><label for="brief-competitors">Alternatives or competitors</label><textarea id="brief-competitors" rows="3" maxlength="50000"></textarea><label for="brief-differentiators">Differentiators</label><textarea id="brief-differentiators" rows="3" maxlength="50000"></textarea><label for="brief-constraints">Constraints</label><textarea id="brief-constraints" rows="3" maxlength="50000"></textarea><label for="brief-stakeholders">Stakeholders</label><textarea id="brief-stakeholders" rows="3" maxlength="50000"></textarea><label for="brief-locales">Locales or territories</label><textarea id="brief-locales" rows="3" maxlength="50000"></textarea><label for="brief-success-measures">Success measures</label><textarea id="brief-success-measures" rows="3" maxlength="50000"></textarea><label for="brief-unresolved">Unresolved questions</label><textarea id="brief-unresolved" rows="3" maxlength="50000"></textarea></details><label for="brief-assistance">AI assistance</label><select id="brief-assistance"><option value="advisor">Advisor</option><option value="copilot">Copilot</option><option value="autonomous">Autonomous strategist</option></select><label for="brief-research">Research boundary</label><select id="brief-research"><option value="local_only">Local material only</option><option value="controlled">Controlled external research</option></select><p id="brief-status" role="status" aria-live="polite"></p></form><form id="evidence-form"><h3>Add evidence</h3><p class="field-help">Source type and privacy travel with the observation. “Private local” never grants permission to send it elsewhere.</p><label for="evidence-kind">Source type</label><select id="evidence-kind"><option value="owner">Owner statement</option><option value="project">Project material</option><option value="external">External source</option></select><label for="evidence-privacy">Privacy</label><select id="evidence-privacy"><option value="private-local">Private local</option><option value="research-approved">Approved for task-specific research</option></select><label for="evidence-title">Title</label><input id="evidence-title" required maxlength="300"><label for="evidence-summary">Observation or finding</label><textarea id="evidence-summary" required rows="4" maxlength="50000"></textarea><label for="evidence-locator">Source path or URL (optional)</label><input id="evidence-locator" maxlength="4096"><button type="submit">Add evidence</button><p id="evidence-status" role="status" aria-live="polite"></p></form><ul id="evidence-list" aria-label="Accepted evidence"></ul></section>"""

GENERATION_PANEL = """<section class="generation-panel" aria-labelledby="generation-heading"><h2 id="generation-heading">Generate a starting point</h2><p class="field-help">A blank page is the enemy of a good brand. Generate a draft to react against, then make it yours — the strongest decisions come from editing something wrong into something right, not from the first output. <strong>Complete draft</strong> fills every section; <strong>selected section</strong> fills one plus what it depends on. Pause, cancel, and hand-edit freely below.</p><div class="button-row"><button id="generate-complete" type="button">Generate complete draft</button><button id="generate-section" type="button">Generate selected section</button><button id="generate-to-brief" type="button">Update to match brief</button><button id="pause-generation" type="button" disabled>Pause generation</button><button id="cancel-generation" type="button" disabled>Cancel generation</button></div><p id="generation-status" role="status" aria-live="polite"></p><ol id="generation-progress" aria-label="Generation progress"></ol></section>"""

# The logo generator sits first: it is the action people reach for before editing prose.
ASSET_PANEL = f"""<section class="asset-panel" aria-labelledby="asset-heading"><h2 id="asset-heading">Logos and production assets</h2><form id="logo-form"><h3>Generate a logo with AI</h3><p class="field-help">Describe constraints, not vibes. "<em>One color, no text, legible at 16 pixels</em>" steers the model far better than "<em>modern and clean</em>" — the tighter the box, the more usable the mark. This draws on the brand's name, context, and color tokens.</p><label for="logo-instructions">Extra instructions (optional)</label><textarea id="logo-instructions" maxlength="2000" rows="3" placeholder="e.g. minimalist line mark, avoid text, evoke a mountain"></textarea><button type="submit">Generate logo</button><p id="logo-status" role="status" aria-live="polite"></p></form><p>Upload logos, fonts, or other production files. Each is stored by content hash and appears in the brand bible's asset registry.</p><ul id="asset-list" aria-label="Registered assets"></ul><form id="asset-form"><label for="asset-name">Asset name</label><input id="asset-name" required maxlength="300" placeholder="e.g. Primary logo (SVG)"><label for="asset-file">File</label><input id="asset-file" type="file" required><label class="asset-required"><input id="asset-required" type="checkbox" checked> Required for publication</label><p class="field-help">Mark an asset <strong>required</strong> only if the brand genuinely breaks without it. Required assets are promises the system keeps — it refuses to publish if one goes missing or changes underneath you. Uncheck for optional or work-in-progress files.</p><button type="submit">Upload asset</button><p id="asset-status" role="status" aria-live="polite"></p></form>{DERIVATIVE_TOOLS}</section>"""


def _group(
    heading: str, editors_id: str, add_id: str, add_label: str, guidance: str, open_by_default: bool
) -> str:
    """One collapsible content group inside the section editor."""

    state = " open" if open_by_default else ""
    return f"""<details class="content-group"{state} data-add="{add_id}"><summary><h3>{heading}</h3><span class="group-count" id="count-{editors_id}"></span></summary><p class="field-help">{guidance}</p><div id="{editors_id}"></div><button id="{add_id}" type="button">{add_label}</button></details>"""


SECTION_GROUPS = (
    _group(
        "Prose",
        "block-editors",
        "add-paragraph",
        "Add paragraph",
        "Write the <em>why</em>, not just the <em>what</em>. A rule tells someone what to do; the reasoning behind it is what stops them relitigating a settled decision six months from now. Capture the thinking while it's fresh — future-you won't remember it.",
        True,
    )
    + _group(
        "Rules",
        "rule-editors",
        "add-rule",
        "Add rule",
        "A rule nobody can break is just a wish. Make each one specific enough to actually fail a real piece of work, and keep them few — every rule is something the brand now has to defend forever. Set enforcement by how much it truly matters: <strong>advisory</strong>, <strong>warning</strong>, or <strong>blocking</strong>.",
        True,
    )
    + _group(
        "Tokens",
        "token-editors",
        "add-token",
        "Add token",
        "Name colors by the job they do — <code>primary</code>, <code>accent</code>, <code>background</code> — never by how they look. Roles survive a rebrand; a token called <code>navy</code> becomes a lie the day the palette changes. Those role names also re-skin the bible live, so use a hex like <code>#1a1a1a</code>.",
        False,
    )
    + _group(
        "Examples",
        "example-editors",
        "add-example",
        "Add example",
        "One sharp <strong>don't</strong> teaches more than three <strong>dos</strong>. Show the plausible-but-wrong version people actually produce — the near-miss, not the obvious mistake nobody was going to make. Tag each as <strong>do</strong>, <strong>don't</strong>, or <strong>context</strong>.",
        False,
    )
    + _group(
        "Patterns",
        "pattern-editors",
        "add-pattern",
        "Add pattern",
        "Patterns are where a brand stops being taste and becomes repeatable. The test: if two people follow the same pattern and get different results, it isn't finished yet. Give each real specifications and do / don't lists (say / never-say, type scale, component specs).",
        False,
    )
)

SECTION_EDITOR = f"""<div class="workshop-grid"><nav id="section-navigation" aria-label="Brand sections"></nav><section aria-labelledby="section-title"><form id="section-form"><h2 id="section-title">Select a section</h2><p class="field-help">Build the brand in passes, not in one sitting. Coherence comes from returning to earlier sections as later ones sharpen your thinking — the voice you write here should change how you write the messaging two sections down. Everything you add flows into the complete brand bible.</p><label for="section-status">Section status</label><select id="section-status" aria-describedby="status-help"><option>incomplete</option><option>draft</option><option>reviewed</option><option>approved</option></select><p id="status-help" class="field-help">Resist approving early. Brands cohere late — a section you lock now often fights a choice you make three sections from here, so let things stay <strong>draft</strong> until the whole system agrees with itself. Move <strong>incomplete → draft → reviewed → approved</strong>; only reviewed and approved count toward completion.</p><div class="completeness"><p id="completeness-label" class="field-help">0 of 5 content types filled.</p><progress id="section-completeness" max="5" value="0" aria-labelledby="completeness-label"></progress></div>{SECTION_GROUPS}<button type="submit">Save section</button><p class="field-help">Edits save on their own a moment after you stop typing. <kbd>⌘S</kbd> saves now; <kbd>⌘Enter</kbd> adds another item to the group you are editing.</p><p id="editor-status" role="status" aria-live="polite"></p></form></section></div>"""


def workspace_index() -> str:
    return f"""<!doctype html><html lang="en"><head>{HEAD}<title>Living brands</title></head><body data-page="index">{HEADER}<main id="main-content"><section class="intro"><p class="eyebrow">Local workspace</p><h1>Build a living brand system</h1><p>Start with whatever exists today. You can change direction later without changing the canonical workspace.</p><form id="workspace-form"><fieldset class="choice-grid"><legend>What are you starting with?</legend><label class="choice-card"><input type="radio" name="entry-path" value="raw_idea"> <strong>Raw idea</strong><span>I need help shaping the concept, audience, position, and possibly the name.</span></label><label class="choice-card"><input type="radio" name="entry-path" value="named_concept" checked> <strong>Named concept</strong><span>I have a name or clear concept and want to build its system.</span></label><label class="choice-card"><input type="radio" name="entry-path" value="existing_project"> <strong>Existing project</strong><span>I want to preserve what works and improve an established project.</span></label></fieldset><fieldset class="choice-grid"><legend>How should AI help?</legend><label class="choice-card"><input type="radio" name="assistance-mode" value="advisor"> <strong>Advisor</strong><span>Ask, analyze, and recommend; I make each change.</span></label><label class="choice-card"><input type="radio" name="assistance-mode" value="copilot" checked> <strong>Copilot</strong><span>Draft alongside me and wait for acceptance.</span></label><label class="choice-card"><input type="radio" name="assistance-mode" value="autonomous"> <strong>Autonomous strategist</strong><span>Take initiative within the brief; validation and provenance still apply.</span></label></fieldset><fieldset class="choice-grid compact-choices"><legend>Research boundary</legend><label class="choice-card"><input type="radio" name="research-mode" value="local_only"> <strong>Local material only</strong><span>Nothing external is researched.</span></label><label class="choice-card"><input type="radio" name="research-mode" value="controlled" checked> <strong>Controlled research</strong><span>External research is task-specific, disclosed, and cited.</span></label></fieldset><label for="workspace-name">Brand or working name</label><input id="workspace-name" required maxlength="300" placeholder="e.g. Northstar Books"><label for="brand-context">What do you already know? (optional)</label><textarea id="brand-context" maxlength="50000" rows="8" aria-describedby="brand-context-help" placeholder="e.g. We serve independent neighborhood bookstores fighting Amazon. Our reader is a shop owner who knows every regular by name. We sound literate and warm — never nostalgic, never corporate. The one thing only we'd say: 'A store is an argument for a kind of town.'"></textarea><p id="brand-context-help" class="field-help">A few real specifics beat a page of adjectives. Name the audience, tension, constraint, or sentence only this project would say. The structured brief can be completed a little at a time.</p><label for="owner-name">Your name</label><input id="owner-name" required maxlength="300" placeholder="e.g. Alex Rivera"><button type="submit">Create workspace</button><p id="workspace-status" role="status" aria-live="polite"></p></form></section><section aria-labelledby="workspaces-heading"><h2 id="workspaces-heading">Your workspaces</h2><div id="workspace-list" aria-busy="true"><p>Loading…</p></div></section></main></body></html>"""


def workspace_detail(brand_id: UUID) -> str:
    return f'''<!doctype html><html lang="en"><head>{HEAD}<title>Brand workshop</title></head><body data-page="workshop" data-brand-id="{brand_id}">{HEADER}<main id="main-content"><div class="workshop-head"><p class="eyebrow">Living brand</p><h1 id="brand-title">Loading workspace…</h1><p id="revision-label"></p></div>{BRIEF_PANEL}{GENERATION_PANEL}{ASSET_PANEL}{SECTION_EDITOR}</main></body></html>'''
